package com.designly.project;import jakarta.persistence.*;import java.time.Instant;@Entity public class DesignProject{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;private String title;private String category;@Column(columnDefinition="TEXT") private String designJson;private Instant updatedAt=Instant.now();public Long getId(){return id;}public String getTitle(){return title;}public void setTitle(String v){title=v;}public String getCategory(){return category;}public void setCategory(String v){category=v;}public String getDesignJson(){return designJson;}public void setDesignJson(String v){designJson=v;}public Instant getUpdatedAt(){return updatedAt;}public void setUpdatedAt(Instant v){updatedAt=v;}}